// Combina el body del webhook (tipo, documentoUrl) con la reserva completa
// recién consultada (cliente, viaje, etc.) para armar el mensaje.
const body = $('Documento emitido').item.json.body; // { tipo, reservaId, documentoUrl }
const rsv = $json; // GET /api/reservas/:id
const cli = rsv.cliente || {};
const v = rsv.cotizacion?.viaje || {};
const ruta = (v.origen?.codigoIATA && v.destino?.codigoIATA)
  ? `${v.origen.codigoIATA} → ${v.destino.codigoIATA}`
  : 'tu viaje';
const fechaViaje = rsv.fechaViaje ? new Date(rsv.fechaViaje).toLocaleDateString('es-AR') : '';
const tel = (cli.telefono || '').replace(/^whatsapp:/, '');
// Fase S3: el back ya manda documentoUrl absoluta y firmada (HMAC +
// vencimiento) — antes era una ruta relativa y este nodo le anteponía
// el host a mano; ya no hace falta (ni corresponde, tiene sig incluida).
const documentoUrl = body.documentoUrl || null;

let mensaje = '';
if (body.tipo === 'VOUCHER') {
  mensaje = documentoUrl
    ? `📄 *¡Tu voucher está listo!*\n\nHola ${cli.nombre}, ya generamos el voucher de tu reserva ${rsv.numeroReserva} (${ruta} - ${fechaViaje}). Descargalo acá:\n${documentoUrl}\n\nTambién te lo mandamos por mail con el archivo adjunto. Llevalo impreso o en el celular el día del viaje. ✈️`
    : `Hola ${cli.nombre}, emitimos tu voucher pero no pudimos generar el link. Nos comunicamos a la brevedad.`;
} else if (body.tipo === 'CONTRATO') {
  mensaje = documentoUrl
    ? `📑 *¡Tu contrato está listo!*\n\nHola ${cli.nombre}, ya generamos el contrato de servicios de tu reserva ${rsv.numeroReserva} (${ruta} - ${fechaViaje}). Podés verlo acá:\n${documentoUrl}\n\nTambién te lo mandamos por mail con el archivo adjunto para que lo guardes. Cualquier consulta, escribinos por acá. ✈️`
    : `Hola ${cli.nombre}, emitimos tu contrato pero no pudimos generar el link. Nos comunicamos a la brevedad.`;
} else {
  mensaje = `Hola ${cli.nombre}, te escribimos desde STG sobre tu reserva ${rsv.numeroReserva}.`;
}

return [{ json: {
  tipo: body.tipo, telefono: tel, mensaje, reservaNumero: rsv.numeroReserva,
  email: cli.email || null, documentoUrl, nombreCliente: cli.nombre || ''
} }];
